    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO pin
int set_gpio_direction(int pin, const char *direction)
{
    struct gpiod_line *line;
    if (pin == GPIO_PIN_1) {
        line = line1;
    } else if (pin == GPIO_PIN_2) {
        line = line2;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set direction for line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to write a value to a GPIO pin
int write_gpio_value(int pin, int value)
{
    struct gpiod_line *line;
    if (pin == GPIO_PIN_1) {
        line = line1;
    } else if (pin == GPIO_PIN_2) {
        line = line2;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";

    struct gpiod_line *line;
    if (pin == GPIO_PIN_1) {
        line = line1;
    } else if (pin == GPIO_PIN_2) {
        line = line2;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(GPIO_PIN_1) < 0 || export_gpio(GPIO_PIN_2) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(GPIO_PIN_1, "out") < 0 || set_gpio_direction(GPIO_PIN_2, "out") < 0) {
        unexport_gpio(GPIO_PIN_1);
        unexport_gpio(GPIO_PIN_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Toggle GPIO 2
        if (write_gpio_value(GPIO_PIN_1, 1) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        sleep(1);

        if (write_gpio_value(GPIO_PIN_1, 0) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        sleep(1);

        // Toggle GPIO 3
        if (write_gpio_value(GPIO_PIN_2, 1) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        sleep(1);

        if (write_gpio_value(GPIO_PIN_2, 0) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        sleep(1);
    }

    // Unexport GPIO pins
    unexport_gpio(GPIO_PIN_1);
    unexport_gpio(GPIO_PIN_2);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(GPIO_2, 1);
        gpioWrite(GPIO_3, 0);
        printf("GPIO 2 HIGH, GPIO 3 LOW\n");
        gpioDelay(100000); // 0.1 seconds

        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
        printf("GPIO 2 LOW, GPIO 3 HIGH\n");
        gpioDelay(100000); // 0.1 seconds
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_LINE 0
#define GPIO_PATH "/sys/class/gpio/gpio2"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    int value;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_input(line, "gpio2");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        if (value == 0) {
            if (gpiod_line_set_value(line, 1) < 0) {
                fprintf(stderr, "Error setting GPIO line value to 1: %s\n", strerror(errno));
                break;
            }
            printf("Setting GPIO %d HIGH\n", GPIO_PIN);
        } else if (value == 1) {
            if (gpiod_line_set_value(line, 0) < 0) {
                fprintf(stderr, "Error setting GPIO line value to 0: %s\n", strerror(errno));
                break;
            }
            printf("Setting GPIO %d LOW\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
        }

        sleep(5);
    }

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to write a 16-bit value to the ADS1115 configuration register
int write_config(int handle, int16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the ADS1115 conversion register
int16_t read_conversion(int handle) {
    char buf[1];
    char read_buf[2];

    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion register: %d\n", result);
        return -1;
    }

    return (int16_t)((read_buf[0] << 8) | read_buf[1]);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Write configuration to start conversion
        if (write_config(i2c_handle, CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE) != 0) {
            fprintf(stderr, "Error writing config. Exiting.\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10000); // 10 ms

        // Read conversion result
        int16_t raw_value = read_conversion(i2c_handle);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading conversion. Exiting.\n");
            break;
        }

        // Print the reading
        printf("Raw ADC Value: %d\n", raw_value);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500 ms
    }

    // Close I2C device and terminate pigpio (should not reach here normally due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

