#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define TA_REG 0x06

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from MLX90614
float read_mlx90614_temp() {
    unsigned char buf[2];
    int result;

    // Read two bytes from the temperature register
    result = ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR);
    if (result < 0) {
        perror("Error setting I2C slave address");
        return -1000.0; // Indicate error
    }

    result = read(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Error reading from I2C device");
        return -1000.0; // Indicate error
    }

    // Convert the two bytes to a 16-bit value
    int raw_temp = (buf[1] << 8) | buf[0];

    // Convert the raw value to Celsius (formula from datasheet)
    float temp_celsius = (float)raw_temp * 0.02 - 273.15;

    return temp_celsius;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    printf("MLX90614 Temperature Reader\n");

    while (1) {
        float temp = read_mlx90614_temp();

        if (temp > -999.0) {
            printf("Temperature: %.2f °C\n", temp);
        } else {
            fprintf(stderr, "Error reading temperature. Check I2C connection.\n");
        }

        sleep(5);
    }

    return 0;
}

