#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define GAIN_4_096V 0x0000 // Gain of 4.096V
#define SINGLE_CONVERSION_MODE 0x8000 // Start single conversion
#define SAMPLE_INTERVAL_MS 100

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a register value to the ADS1115
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a register value from the ADS1115
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single conversion
        uint16_t config = SINGLE_CONVERSION_MODE | GAIN_4_096V | 0x0080; // Start single conversion
        if (write_register(i2c_fd, CONFIG_REG, config) < 0) {
            fprintf(stderr, "Error configuring ADS1115. Exiting.\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t conversion;
        if (read_register(i2c_fd, CONVERSION_REG, &conversion) < 0) {
            fprintf(stderr, "Error reading ADS1115 conversion. Exiting.\n");
            break;
        }

        // Calculate voltage
        float voltage = (float)conversion * REF_VOLTAGE / 32768.0;

        // Print voltage
        printf("Voltage: %.4f V\n", voltage);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

