#define PWM_GPIO 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        printf("PWM on GPIO %d: 0\n", PWM_GPIO);
        gpioPWM(PWM_GPIO, 0);
        gpioDelay(500000); // 0.5 seconds

        printf("PWM on GPIO %d: 100\n", PWM_GPIO);
        gpioPWM(PWM_GPIO, 100);
        gpioDelay(500000); // 0.5 seconds
    }

    gpioPWM(PWM_GPIO, 0); // Ensure PWM is off on exit
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
