#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float getDistance();
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
    gpioTerminate();
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long start = gpioTick();
    long now;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        now = gpioTick();
        if (now - start > timeout) {
            return 0; // Timeout
        }
    }

    start = gpioTick();
    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        now = gpioTick();
        if (now - start > timeout) {
            return 0; // Timeout
        }
    }

