    echo_end_tick = 0;

    long start = gpioTick();
    long end = gpioTick();

    // Wait for echo to start
    while (gpioRead(ECHO_PIN) == 0) {
        start = gpioTick();
        if (start - end > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    echo_start_tick = gpioTick();

    // Wait for echo to end
    while (gpioRead(ECHO_PIN) == 1) {
        end = gpioTick();
        if (end - start > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    echo_end_tick = gpioTick();

    long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);
    if (pulse_width == 0) {
        return -1.0; // Timeout
    }

    // Calculate distance in centimeters
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance
    return distance;
}

