// Function to write a register value to the ADS1115
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a register value from the ADS1115
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = buf[0];
    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc(int fd) {
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t raw_value;

    if (write_register(fd, CONFIG_REG, config) != 0) {
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    if (read_register(fd, CONVERSION_REG, &raw_value) != 0) {
        return -1;
    }

    return (int16_t)raw_value;
}

