int is_valid_reading(int16_t reading) {
    // Basic validation: check if the reading is within a reasonable range
    // You can adjust the range based on your specific application and sensor
    const int16_t MIN_VALUE = -2048; // Minimum value for 12-bit ADC
    const int16_t MAX_VALUE = 2047;  // Maximum value for 12-bit ADC

    return (reading >= MIN_VALUE && reading <= MAX_VALUE);
}

