#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5

int i2c_fd;

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg_addr, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read temperature from the SI7021
int read_temperature(float *temperature) {
    uint16_t raw_temp;
    if (read_i2c_word(i2c_fd, MEASURE_TEMP_CMD, &raw_temp) != 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return -1;
    }

    // Convert raw temperature to Celsius (see SI7021 datasheet)
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return 0;
}

// Function to read humidity from the SI7021
int read_humidity(float *humidity) {
    uint16_t raw_humidity;
    if (read_i2c_word(i2c_fd, MEASURE_HUMID_CMD, &raw_humidity) != 0) {
        fprintf(stderr, "Failed to read humidity\n");
        return -1;
    }

    // Convert raw humidity to percentage relative humidity (see SI7021 datasheet)
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return 0;
}

int main() {
    float temperature, humidity;
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        ret = read_temperature(&temperature);
        if (ret != 0) {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        ret = read_humidity(&humidity);
        if (ret != 0) {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate readings
        if (temperature < -40.0 || temperature > 85.0) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
        } else if (humidity < 0.0 || humidity > 100.0) {
            fprintf(stderr, "Invalid humidity reading: %.2f\n", humidity);
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        }

        sleep(5);
    }

    // Close I2C bus (this part will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;

// Function to write a register
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buf[0];
    return 0;
}

int main() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, single conversion
    if (write_register(i2c_fd, CONFIG_REG, 0xC283) < 0) {
        close(i2c_fd);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        usleep(1000000); // 1 second

        uint16_t raw_value;
        if (read_register(i2c_fd, CONVERSION_REG, &raw_value) < 0) {
            close(i2c_fd);
            return 1;
        }

        float voltage = (float)raw_value * REF_VOLTAGE / 32768.0;
        printf("Voltage: %.3f V\n", voltage);
    }

    close(i2c_fd);
    return 0;
}

