// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on a given GPIO pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long start = gpioTick();
    long now;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        now = gpioTick();
        if (now - start > timeout) {
            return 0; // Timeout
        }
    }

    start = gpioTick();
    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        now = gpioTick();
        if (now - start > timeout) {
            return 0; // Timeout
        }
    }

    width = gpioTick() - start;
    return width;
}

// Function to measure the distance using the HC-SR04 sensor
float getDistance() {
    triggerSensor();

    echo_start_tick = 0;
    echo_end_tick = 0;

    // Wait for echo to start (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }
    echo_start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }
    echo_end_tick = gpioTick();

    // Calculate pulse width in microseconds
    long pulse_width = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

    if (pulse_width <= 0) {
        fprintf(stderr, "Error: Invalid pulse width: %ld\n", pulse_width);
        return -1.0; // Indicate error
    }

    // Calculate distance in centimeters
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance

    return distance;
}

