#include <unistd.h>
#include <errno.h>

#define NUM_GPIOS 9

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_GPIOS];
static volatile sig_atomic_t keep_running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize a GPIO line
int init_gpio(int gpio)
{
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the line for the GPIO
    lines[gpio] = gpiod_chip_get_line(chip, gpio);
    if (!lines[gpio]) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure the line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(lines[gpio], &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", gpio, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(int gpio, int value)
{
    if (gpiod_line_set_value(lines[gpio], value) < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO line
void report_gpio_state(int gpio, int value)
{
    printf("GPIO %d: %s\n", gpio, value ? "HIGH" : "LOW");
}

int main()
{
    int i, value;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    for (i = 2; i <= 17; i++) {
        if (init_gpio(i) < 0) {
            fprintf(stderr, "Failed to initialize GPIO %d. Exiting.\n", i);
            // Clean up already initialized lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                if (lines[j]) {
                    gpiod_line_release(lines[j]);
                }
            }
            if (chip) {
                gpiod_chip_close(chip);
            }
            return 1;
        }
    }

    // Main loop
    while (keep_running) {
        for (i = 2; i <= 17; i++) {
            value = (i % 2 == 0) ? 1 : 0; // Alternate HIGH/LOW for even/odd GPIOs
            if (set_gpio_state(i, value) < 0) {
                fprintf(stderr, "Failed to set GPIO %d state. Exiting.\n", i);
                break; // Exit loop on error
            }
            report_gpio_state(i, value);
        }
        usleep(50000); // 50ms delay
    }

    // Clean up GPIO lines
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

