#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    close(i2c_fd);
    exit(0);
}

// Function to read a 16-bit value from the OPT3001
int16_t read_opt3001(int fd) {
    uint8_t buf[2];
    int16_t raw_value;

    // Read two bytes from the result register
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    raw_value = (buf[0] << 8) | buf[1];

    return raw_value;
}

// Function to convert the raw value to temperature in Celsius
float convert_to_celsius(int16_t raw_value) {
    // Extract exponent and result from the raw value
    int exponent = (raw_value >> 12) & 0x0F;
    int result = raw_value & 0x0FFF;

    // Calculate the temperature in Celsius
    float temperature = result * (0.5 * exponent) + 0.5;

    return temperature;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the OPT3001
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the OPT3001 for continuous conversion mode
    uint16_t config_value = 0b110000000000; // Continuous conversion mode, 100ms conversion time
    uint8_t config_buf[2];
    config_buf[0] = CONFIG_REG;
    config_buf[1] = (config_value >> 8) & 0xFF;
    if (write(i2c_fd, config_buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print the temperature
    while (1) {
        int16_t raw_value = read_opt3001(i2c_fd);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading OPT3001, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        float temperature = convert_to_celsius(raw_value);
        printf("Temperature: %.2f °C\n", temperature);

        usleep(500000); // Wait 500ms
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

