    char w1_slave_path[256];
    char line[256];
    int fd;
    char *token;
    float temperature = -999.0; // Default invalid value
    int retries = 0;

    // Construct the path to the w1_slave file
    snprintf(w1_device_path, sizeof(w1_device_path), "%s/%s", W1_DEVICES_PATH, W1_SLAVE_FILE);

    // Retry mechanism
    while (retries < MAX_RETRIES) {
        // Open the w1_slave file for reading
        fd = open(w1_device_path, O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "Error opening %s: %s\n", w1_device_path, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Read the contents of the file
        ssize_t bytes_read = read(fd, line, sizeof(line) - 1);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading %s: %s\n", w1_device_path, strerror(errno));
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }
        line[bytes_read] = '\0';

        // Check for the presence of the CRC check
        if (strstr(line, "YES") == NULL) {
            fprintf(stderr, "CRC check failed\n");
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        // Find the temperature value
        token = strstr(line, "t=");
        if (token != NULL) {
            long temp_milli_celsius = strtol(token + 2, NULL, 10);
            temperature = (float)temp_milli_celsius / 1000.0;
        } else {
            fprintf(stderr, "Temperature value not found\n");
            close(fd);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        close(fd);
        return temperature;
    }

    // If all retries failed, return the default invalid value
