// Function to read temperature and humidity from HTU21D
int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t cmd = 0xE3; // Trigger temperature measurement
    uint8_t data[3];
    int result;

    // Send temperature measurement command
    result = write(fd, &cmd, 1);
    if (result != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 50ms)
    usleep(50000); // 50ms

    // Read 3 bytes of data
    result = read(fd, data, 3);
    if (result != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[2] << 8) | data[3];

    // Check temperature validity
    if (raw_temperature > 0x8000) {
        fprintf(stderr, "Temperature out of range: 0x%X\n", raw_temperature);
        return -1;
    }

    *temperature = -46.85 + 175.72 * ((float)raw_temperature / 65536.0);
    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    // Check humidity validity
    if (*humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", *humidity);
        return -1;
    }

    return 0;
}

