#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int pin) {
    int i;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int pulse_start, pulse_end;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(1);
    gpioWrite(pin, 1);
    gpioDelay(30); // Changed from 40 to 30 as per DHT22 datasheet

    gpioSetMode(pin, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(pin) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(pin) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Wait for the DHT22 to pull the line low again
    timeout = 0;
    while (gpioRead(pin) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(pin) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }

        // Measure the pulse length
        pulse_start = gpioTick();
        timeout = 0;
        while (gpioRead(pin) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }
        pulse_end = gpioTick();

        // Determine if it's a 0 or a 1 based on the pulse length
        if ((pulse_end - pulse_start) > 40) { // Changed from 50 to 40
            data[byte_index] <<= 1;
            if (pulse_end - pulse_start > 28) {
                data[byte_index] |= 1;
            }
        } else {
            data[byte_index] <<= 1;
            data[byte_index] |= 0;
        }

        bit_count++;
        if (bit_count == 8) {
            byte_index++;
            bit_count = 0;
        }
    }

    // Verify checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1; // Checksum error
    }

    return (data[0] << 8) | data[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int result1 = read_dht22(DHT22_PIN_1);
        int result2 = read_dht22(DHT22_PIN_2);
        int result3 = read_dht22(DHT22_PIN_3);
        int result4 = read_dht22(DHT22_PIN_4);

        if (result1 == -1) {
            fprintf(stderr, "DHT22 on GPIO %d: Error reading data\n", DHT22_PIN_1);
        } else {
            printf("DHT22 on GPIO %d: %d\n", DHT22_PIN_1, result1);
        }

        if (result2 == -1) {
            fprintf(stderr, "DHT22 on GPIO %d: Error reading data\n", DHT22_PIN_2);
        } else {
            printf("DHT22 on GPIO %d: %d\n", DHT22_PIN_2, result2);
        }

        if (result3 == -1) {
            fprintf(stderr, "DHT22 on GPIO %d: Error reading data\n", DHT22_PIN_3);
        } else {
            printf("DHT22 on GPIO %d: %d\n", DHT22_PIN_3, result3);
        }

        if (result4 == -1) {
            fprintf(stderr, "DHT22 on GPIO %d: Error reading data\n", DHT22_PIN_4);
        } else {
            printf("DHT22 on GPIO %d: %d\n", DHT22_PIN_4, result4);
        }

        sleep(2);
    }

    gpioTerminate();
    return 0;
}

