int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM output
    if (gpioSetMode(PWM_GPIO_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", PWM_GPIO_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(PWM_GPIO_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", PWM_GPIO_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(PWM_GPIO_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", PWM_GPIO_3);
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    if (gpioSetPWMrange(PWM_GPIO_1, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_GPIO_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(PWM_GPIO_2, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_GPIO_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(PWM_GPIO_3, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_GPIO_3);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency (e.g., 1000 Hz)
    if (gpioSetPWMfrequency(PWM_GPIO_1, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_GPIO_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO_2, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_GPIO_2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO_3, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", PWM_GPIO_3);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Set PWM duty cycle (0-255) for each GPIO
        gpioPWM(PWM_GPIO_1, 128); // 50% duty cycle
        gpioPWM(PWM_GPIO_2, 192); // 75% duty cycle
        gpioPWM(PWM_GPIO_3, 64);  // 25% duty cycle

        // Print the duty cycle values
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", PWM_GPIO_1, 128, PWM_GPIO_2, 192, PWM_GPIO_3, 64);

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Stop PWM output before exiting
    gpioPWM(PWM_GPIO_1, 0);
    gpioPWM(PWM_GPIO_2, 0);
    gpioPWM(PWM_GPIO_3, 0);

    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

