int export_gpio(int pin)
{
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_chip_get_line(chip, pin, &config);
    if (ret < 0) {
        fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to set the direction of a GPIO pin
int set_gpio_direction(int pin, int direction)
{
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_direction";
    config.request_type = direction == 0 ? GPIOD_LINE_REQUEST_DIRECTION_INPUT : GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting direction for pin %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to write a value to a GPIO pin
int write_gpio_value(int pin, int value)
{
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_write";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line for write: %s\n", strerror(-ret));
        return -1;
    }

    ret = gpiod_line_set_value(line1, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for pin %d: %s\n", pin, strerror(-ret));
        return -1;
    }

    return 0;
}

