int unexport_gpio(int pin)
{
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line1, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line for unexport: %s\n", strerror(-ret));
        return -1;
    }

    ret = gpiod_line_release(line1);
