#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor (PON and AEN)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable sensor.\n");
        return -1;
    }

    // Set integration time (ATIME) - e.g., 2.4ms
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Could not set integration time.\n");
        return -1;
    }

    // Set gain (AGAIN) - e.g., 60x
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Could not set gain.\n");
        return -1;
    }

    return 0;
}

// Function to read the color data from the sensor
int read_color_data(unsigned int *red, unsigned int *green, unsigned int *blue, unsigned int *clear) {
    unsigned char buffer[8];

    // Read the clear, red, green, and blue data in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data.\n");
        return -1;
    }

    // Combine the bytes to form the 16-bit color values
    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

