// Function to initialize the camera
int init_camera(const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(log_file, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(log_file, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(log_file, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(log_file, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(log_file, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(log_file, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(log_file, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(log_file, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(log_file, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(log_file, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

