// Function to initialize the SSD1306 display
int ssd1306_init()
{
    // Initialization sequence (refer to SSD1306 datasheet)
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Multiplex ratio
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    int result;
    for (int i = 0; i < sizeof(init_commands) / sizeof(init_commands[0]); i++) {
        result = i2cWriteByteData(i2c_handle, init_commands[i], init_commands[i+1]);
        if (result != 0) {
            fprintf(stderr, "Error writing to SSD1306 during initialization: %d\n", result);
            return -1;
        }
    }

    return 0;
}

