// Function to export a GPIO pin
int export_gpio(int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d for export\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0); // 0 for unbuffered request
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for export: %s\n", pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

