// Function to trigger the HC-SR04 sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long measure_pulse_width()
{
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    return (pulse_width * 0.0343) / 2.0;
