#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 2.0      // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int valid_reading = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start, uint32_t end);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            valid_reading = 0; // Reset validity flag
        } else if (level == 0) {
            echo_end_tick = tick;
            uint32_t diff = echo_end_tick - echo_start_tick;

            if (diff > 0 && diff < TIMEOUT_US) {
                double distance = calculate_distance(echo_start_tick, echo_end_tick);
                if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                    printf("Distance: %.2f cm\n", distance);
                    valid_reading = 1; // Set validity flag
                } else {
                    printf("Invalid distance reading: %.2f cm\n", distance);
                }
            } else {
                printf("Timeout or invalid echo pulse\n");
            }
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    return (diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
}

