int publish_mqtt_message(const char *topic, const char *payload) {
    int rc;
    char payload_str[256];
    snprintf(payload_str, sizeof(payload_str), "%s", payload);

    rc = mosquitto_publish(mqtt_client, NULL, topic, strlen(payload_str), payload_str, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
