    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error creating MQTT client\n");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, NULL);
    mosquitto_disconnect_callback_set(mqtt_client, NULL);
    mosquitto_subscribe_callback_set(mqtt_client, NULL);

    int rc = mosquitto_connect(mqtt_client, MQTT_BROKER_ADDRESS, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        char sensor1_data[10], sensor2_data[10];

        if (read_sensor_data(SENSOR1_GPIO, sensor1_data) == 0) {
