#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
static volatile int running = 1;
static volatile int echo_received = 0;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;

// Function prototypes
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick, void *user);
float measure_distance();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that the start of the pulse has been received
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1; // Indicate that the end of the pulse has been received
    }
}

// Function to measure distance using HC-SR04
float measure_distance() {
    echo_received = 0; // Reset echo flag
    start_tick = 0;     // Reset start tick
    end_tick = 0;       // Reset end tick

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo or timeout
    uint32_t start_time = gpioTick();
    while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (!echo_received) {
        fprintf(stderr, "Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    // Calculate pulse duration
    uint32_t pulse_duration = end_tick - start_tick;

    // Calculate distance
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin (optional, but recommended)
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance.\n");
        }

        gpioDelay(200000); // 200 ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
