int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 500); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 750); // 75% duty cycle
        gpioPWM(PWM_PIN_3, 250); // 25% duty cycle
        gpioPWM(PWM_PIN_4, 1000); // 100% duty cycle

        // Print the duty cycle values
        printf("PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d, PWM_PIN_4: %d\n", 500, 750, 250, 1000);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Stop PWM output on all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
