// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int sensor_type;
    int reading;
} sensor_data_t;

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static pthread_mutex_t mqtt_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void signal_handler(int sig);
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port, int keepalive);
int mqtt_publish(struct mosquitto *mosq, const char *topic, const char *payload);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic);
int mqtt_disconnect(struct mosquitto *mosq);
