// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT connect function
int mqtt_connect(struct mosquitto **mosq, const char *client_id, const char *host, int port, int keepalive) {
    *mosq = mosquitto_new(client_id, true, NULL);
    if (!*mosq) {
        syslog(LOG_ERR, "Error creating mosquitto instance.");
        return -1;
    }

    int rc = mosquitto_connect(*mosq, host, port, keepalive);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error connecting to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return -1;
    }

    rc = mosquitto_loop_start(*mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error starting mosquitto loop: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(*mosq);
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return -1;
    }

    return 0;
}

// MQTT publish function
int mqtt_publish(struct mosquitto *mosq, const char *topic, const char *payload) {
    int rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error publishing message: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// MQTT subscribe function
int mqtt_subscribe(struct mosquitto *mosq, const char *topic) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error subscribing to topic: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// MQTT disconnect function
int mqtt_disconnect(struct mosquitto *mosq) {
    int rc = mosquitto_disconnect(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Error disconnecting from MQTT broker: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Validate sensor reading
int validate_reading(int reading, int sensor_type) {
    if (sensor_type == 1) { // Temperature
        if (reading < -50 || reading > 100) {
            syslog(LOG_ERR, "Invalid temperature reading: %d", reading);
            return -1;
        }
    } else if (sensor_type == 2) { // Heart Rate
        if (reading < 0 || reading > 200) {
            syslog(LOG_ERR, "Invalid heart rate reading: %d", reading);
            return -1;
        }
    } else {
        syslog(LOG_ERR, "Unknown sensor type: %d", sensor_type);
        return -1;
    }
    return 0;
