// Publish sensor reading
int publish_sensor_reading(int sensor_id, int sensor_type, int reading) {
    char payload[100];
    snprintf(payload, sizeof(payload), "%d,%d,%d", sensor_id, sensor_type, reading);

    pthread_mutex_lock(&mqtt_mutex);
    if (mqtt_publish(mosq, MQTT_TOPIC_READING, payload) != 0) {
        syslog(LOG_ERR, "Failed to publish sensor reading for sensor %d", sensor_id);
    }
    pthread_mutex_unlock(&mqtt_mutex);
    return 0;
}

// Publish status
void publish_status(const char *status) {
    pthread_mutex_lock(&mqtt_mutex);
    if (mqtt_publish(mosq, MQTT_TOPIC_STATUS, status) != 0) {
        syslog(LOG_ERR, "Failed to publish status: %s", status);
    }
    pthread_mutex_unlock(&mqtt_mutex);
}

// Publish error
void publish_error(const char *error) {
    pthread_mutex_lock(&mqtt_mutex);
    if (mqtt_publish(mosq, MQTT_TOPIC_ERROR, error) != 0) {
        syslog(LOG_ERR, "Failed to publish error: %s", error);
    }
    pthread_mutex_unlock(&mqtt_mutex);
}

// Sensor thread function
void *sensor_thread(void *arg) {
