        mqtt_disconnect(mosq);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Create sensor threads
    pthread_t threads[MAX_SENSORS];
    sensor_data_t sensor_data[MAX_SENSORS];
    int sensor_ids[MAX_SENSORS] = {1, 2, 3, 4}; // Example sensor IDs
    int sensor_types[MAX_SENSORS] = {1, 2, 1, 2}; // Example sensor types (Temperature, Heart Rate)

    for (int i = 0; i < MAX_SENSORS; i++) {
        sensor_data[i].sensor_id = sensor_ids[i];
        sensor_data[i].sensor_type = sensor_types[i];
        if (pthread_create(&threads[i], NULL, sensor_thread, &sensor_data[i]) != 0) {
            syslog(LOG_ERR, "Failed to create thread for sensor %d", sensor_ids[i]);
            running = 0; // Stop other threads
            break;
        }
    }

    // Main loop
    while (running) {
        // Check for MQTT status messages
        int rc = mosquitto_loop(mosq, 100, 1); // Timeout of 100ms
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_WARNING, "MQTT loop error: %s", mosquitto_strerror(rc));
        }

        // Check for signal to exit
        if (!running) break;

        sleep(1); // Check every second
    }

    // Clean up
    syslog(LOG_INFO, "Cleaning up...");
    for (int i = 0; i < MAX_SENSORS; i++) {
        pthread_join(threads[i], NULL);
    }

    mqtt_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

