// Global variables
static int i2c_handle;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_ads1115(int handle, int16_t *adc_value);
int publish_mqtt(const char *topic, const char *payload);
void signal_handler(int sig);
int setup_i2c();
void cleanup();

// Signal handler
void signal_handler(int sig)
{
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Setup I2C
int setup_i2c()
{
    i2c_handle = i2cOpen(ADS1115_I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup()
{
    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }
    if (mosq)
    {
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

// Read ADS1115 ADC value
int read_ads1115(int handle, int16_t *adc_value)
{
    // Configure ADS1115 for single-shot conversion
    uint16_t config = ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_PGA_4_096V | ADS1115_MUX_DIFF_0_4GA;
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = config & 0xFF; //LSB
    buf[2] = (config >> 8) & 0xFF; //MSB

    if (i2cWriteDevice(handle, buf, 3) != 0)
    {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10);

    // Read conversion register
    buf[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(handle, buf, 1) != 0)
    {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
    {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    int16_t raw_value = (data[0] << 8) | data[1];

    // Basic data validation
    if (raw_value < -2048 || raw_value > 2047)
    {
        fprintf(stderr, "Invalid ADC value: %d\n", raw_value);
        return -1;
    }

    *adc_value = raw_value;
    return 0;
}

// Publish MQTT message
int publish_mqtt(const char *topic, const char *payload)
{
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup I2C
    if (setup_i2c() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq)
    {
        fprintf(stderr, "Error creating mosquitto instance\n");
        cleanup();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS)
    {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Subscribe to topic (optional, but good practice)
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t adc_value;
    int16_t threshold = 500; // Example threshold

    // Main loop
    while (running)
    {
        if (read_ads1115(i2c_handle, &adc_value) == 0)
        {
            // Validate sensor reading
            if (adc_value >= -2048 && adc_value <= 2047)
            {
                // Publish MQTT message
                char payload[50];
                snprintf(payload, sizeof(payload), "ADC Value: %d", adc_value);

                if (publish_mqtt(MQTT_TOPIC, payload) != 0)
                {
                    fprintf(stderr, "Failed to publish MQTT message\n");
                }
            }
            else
            {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            }
        }
        else
        {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
        printf("Ctrl+C detected. Exiting.\n");
    }
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio17", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (high)");
            break;
        }
        value = 1;
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (low)");
            break;
        }
        value = 0;
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        usleep(50000); // 50ms
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile int keep_running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the GPIO line state
int set_gpio_state(int value)
{
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %d\n", ret);
        return -1;
    }
    return 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        if (set_gpio_state(1) == 0) {
            printf("GPIO %d set to HIGH\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d to HIGH\n", GPIO_PIN);
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }

        if (set_gpio_state(0) == 0) {
            printf("GPIO %d set to LOW\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d to LOW\n", GPIO_PIN);
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_17 17
#define GPIO_23 23

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line23;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value to %d: %d\n", line->consumer->name, value, ret);
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the lines for GPIO 17 and 23
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("Error getting GPIO 23 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines for output
    if (gpiod_line_request_output(line17, "GPIO17", 0) < 0) {
        perror("Error requesting GPIO 17 line for output");
        gpiod_line_release(line23);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line23, "GPIO23", 0) < 0) {
        perror("Error requesting GPIO 23 line for output");
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial states (HIGH)
    if (set_gpio_state(line17, 1) < 0) return 1;
    if (set_gpio_state(line23, 1) < 0) return 1;

    printf("GPIO 17 and 23 set to HIGH. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        sleep(1); // Keep the program running
    }

    // Release resources before exiting
    gpiod_line_release(line17);
    gpiod_line_release(line23);
    gpiod_chip_close(chip);

    return 0;
}

