#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile int keep_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export the GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_chip_get_line(chip, pin, &line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Export the GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        if (set_gpio_state(line, 1) == 0) {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", GPIO_PIN);
        }
        sleep(1);

        if (set_gpio_state(line, 0) == 0) {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d LOW\n", GPIO_PIN);
        }
        sleep(1);
    }

    // Unexport the GPIO pin
    if (unexport_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    int uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    printf("UART communication started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        } else {
            // No data available, sleep briefly to avoid busy-waiting
            usleep(10000); // 10ms
        }
    }

    close(uart_fd);
    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_mpu6050_word(int fd, uint8_t reg) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read I2C data");
        return -1;
    }
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (set sleep bit to 0)
    uint8_t wake_up = 0x00; // PWR_MGMT_1 register value to wake up the sensor
    if (write(i2c_fd, &wake_up, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = read_mpu6050_word(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6050_word(i2c_fd, ACCEL_YOUT_H);
        int16_t accel_z = read_mpu6050_word(i2c_fd, ACCEL_ZOUT_H);

        // Print the data
        if (accel_x != -1 && accel_y != -1 && accel_z != -1) {
            printf("X: %6d, Y: %6d, Z: %6d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_DEVICE "/dev/i2c-1"

// BMP280 Registers
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables for calibration data
static uint16_t dig_T1;
static int16_t dig_T2;
static int16_t dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2;
static int16_t dig_P3;
static int16_t dig_P4;
static int16_t dig_P5;
static int16_t dig_P6;
static int16_t dig_P7;
static int16_t dig_P8;
static int16_t dig_P9;

static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd) {
    dig_T1 = (i2c_read_byte(fd, BMP280_REG_CALIB_00) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 1);
    dig_T2 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 2) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 3));
    dig_T3 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 4) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 5));
    dig_P1 = (i2c_read_byte(fd, BMP280_REG_CALIB_00 + 6) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 7);
    dig_P2 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 8) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 9));
    dig_P3 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 10) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 11));
    dig_P4 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 12) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 13));
    dig_P5 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 14) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 15));
    dig_P6 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 16) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 17));
    dig_P7 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 18) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 19));
    dig_P8 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 20) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 21));
    dig_P9 = (int16_t)((i2c_read_byte(fd, BMP280_REG_CALIB_00 + 22) << 8) | i2c_read_byte(fd, BMP280_REG_CALIB_00 + 23));

    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t msb, lsb, xlsb;

    msb = i2c_read_byte(fd, BMP280_REG_TEMP_MSB);
    lsb = i2c_read_byte(fd, BMP280_REG_TEMP_LSB);
    xlsb = i2c_read_byte(fd, BMP280_REG_TEMP_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        return -1;
    }

    *raw_temp = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | ((int32_t)xlsb >> 4);

    msb = i2c_read_byte(fd, BMP280_REG_PRESS_MSB);
    lsb = i2c_read_byte(fd, BMP280_REG_PRESS_LSB);
    xlsb = i2c_read_byte(fd, BMP280_REG_PRESS_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        return -1;
    }

    *raw_press = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | ((int32_t)xlsb >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temp / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_press, double t_fine) {
    double var1, var2, p;
    double p_fine;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p_fine = 1048576.0 - (double)raw_press;
    p_fine = (p_fine - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p_fine * p_fine / 2147483648.0;
    var2 = p_fine * ((double)dig_P8) / 32768.0;
    p = (p_fine + (var1 + var2 + ((double)dig_P7)) / 16.0);
    return p;
}

int main() {
    int32_t raw_temp, raw_press;
    double temperature, pressure;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Install signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Set the BMP280 to forced mode
    if (i2c_write_byte(i2c_fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Failed to set BMP280 to forced mode\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temp, &raw_press) != 0) {
            fprintf(stderr, "Failed to read raw data\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temp);
        pressure = compensate_pressure(raw_press, temperature);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print the data
        printf("%s - Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        for (int dutyCycle = 0; dutyCycle <= 255; dutyCycle += 5) {
            if (gpioPWM(PWM_GPIO, dutyCycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", dutyCycle);
                break;
            }
            printf("PWM duty cycle set to %d\n", dutyCycle);
            gpioDelay(100000); // 100ms delay
        }
    }

    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static struct gpiod_chip *chip;
static struct gpiod_line *line5, *line6, *line13;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines for GPIO 5, 6, and 13
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);

    if (!line5 || !line6 || !line13) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(line5, "gpio5", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 5 line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line6, "gpio6", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 6 line for output");
        gpiod_line_release(line5);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line13, "gpio13", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 13 line for output");
        gpiod_line_release(line5);
        gpiod_line_release(line6);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 5 to HIGH
    ret = gpiod_line_set_value(line5, 1);
    if (ret < 0) {
        perror("Error setting GPIO 5 value");
        gpiod_line_release(line5);
        gpiod_line_release(line6);
        gpiod_line_release(line13);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 5 set to HIGH\n");

    // Set GPIO 6 to LOW
    ret = gpiod_line_set_value(line6, 0);
    if (ret < 0) {
        perror("Error setting GPIO 6 value");
        gpiod_line_release(line5);
        gpiod_line_release(line6);
        gpiod_line_release(line13);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 6 set to LOW\n");

    // Set GPIO 13 to HIGH
    ret = gpiod_line_set_value(line13, 1);
    if (ret < 0) {
        perror("Error setting GPIO 13 value");
        gpiod_line_release(line5);
        gpiod_line_release(line6);
        gpiod_line_release(line13);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 13 set to HIGH\n");

    // Keep the program running until a signal is received
    while (keep_running) {
        sleep(1);
    }

    // Release resources
    gpiod_line_release(line5);
    gpiod_line_release(line6);
    gpiod_line_release(line13);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Change this to your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "vehicle/sensor_data"
#define SENSOR_READING_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static int mqtt_handle = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int mqtt_connect();
int mqtt_publish(const char *topic, const char *payload);
void sensor_readings_callback();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (mqtt_handle >= 0) {
        int rc = mqtt_disconnect(mqtt_handle);
        if (rc != 0) {
            fprintf(stderr, "Error disconnecting from MQTT broker: %d\n", rc);
        }
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Connect to MQTT broker
int mqtt_connect() {
    int rc;
    char client_id_str[50];
    snprintf(client_id_str, sizeof(client_id_str), "%s", MQTT_CLIENT_ID);

    mqtt_handle = mosquitto_new(client_id_str, true, NULL);
    if (!mqtt_handle) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    rc = mosquitto_connect(mqtt_handle, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_handle);
        return -1;
    }

    return 0;
}

// Publish a message to the MQTT broker
int mqtt_publish(const char *topic, const char *payload) {
    int rc = mosquitto_publish(mqtt_handle, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not publish message: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Callback function for sensor readings
void sensor_readings_callback() {
    sensor_data_t data;
    time_t rawtime;
