    data.temperature = 25.5 + (rand() % 5) - 2; // Temperature between 23.5 and 27.5
    data.humidity = 60.2 + (rand() % 10) - 5;    // Humidity between 55.2 and 65.2

    // Get current timestamp
    time(&rawtime);
