#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static void *buffer = NULL;
static unsigned int n_buffers = 0;
static int width = 640;
static int height = 480;
static int frame_size = 0;
static char *device_name = "/dev/video0";
static volatile sig_atomic_t keep_running = 1;

// Structure to hold camera configuration
typedef struct {
    int width;
    int height;
    char *device_name;
} camera_config_t;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting...\n");
}

// Function to initialize the camera
int init_camera(const char *device_name, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Use MJPEG for simplicity
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    CLEAR(req);
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    n_buffers = req.count;

    if (buffer == NULL) {
        buffer = calloc(n_buffers, sizeof(void *));
    }

    for (int i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        frame_size = buf.length;
        buffer[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }
    }

    return 0;
}

// Function to start capturing
int start_capturing() {
    struct v4l2_buffer buf;
    for (int i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(char *filename) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    for (int i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            return -1;
        }

        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            perror("Error opening file for writing");
            return -1;
        }

        fwrite(buffer[i], 1, buf.bytesused, fp);
        fclose(fp);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    return 0;
}

// Function to stop capturing
int stop_capturing() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to uninitialize the camera
int uninit_camera() {
    for (int i = 0; i < n_buffers; ++i) {
        if (munmap(buffer[i], frame_size) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    free(buffer);
    close(fd);
    return 0;
}

int main(int argc, char *argv[]) {
    camera_config_t config;

    // Parse command-line arguments
    if (argc > 1) {
        config.device_name = argv[1];
    }
    if (argc > 2) {
        config.width = atoi(argv[2]);
    }
    if (argc > 3) {
        config.height = atoi(argv[3]);
    }

    // Set default values if not provided
    if (config.device_name == NULL) {
        config.device_name = "/dev/video0";
    }
    if (config.width == 0) {
        config.width = 640;
    }
    if (config.height == 0) {
        config.height = 480;
    }

    // Initialize the camera
    if (init_camera(config.device_name, config.width, config.height) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Start capturing
    if (start_capturing() < 0) {
        fprintf(stderr, "Capturing failed to start\n");
        uninit_camera();
        return 1;
    }

    // Capture images every 1 second
    while (keep_running) {
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%03d.jpg", time(NULL));

        if (capture_image(filename) < 0) {
            fprintf(stderr, "Image capture failed\n");
        }

        sleep(1);
    }

    // Stop capturing
    if (stop_capturing() < 0) {
        fprintf(stderr, "Capturing failed to stop\n");
    }

    // Uninitialize the camera
    if (uninit_camera() < 0) {
        fprintf(stderr, "Camera uninitialization failed\n");
    }

    return 0;
}

#include <stdio.h>
