#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static int width = 640;
static int height = 480;
static int frame_nr = 0;
static FILE *log_file = NULL;

// Structure to hold camera parameters
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int width;
    int height;
    int frame_nr;
} camera_params_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (fd != -1) {
        if (buffer != NULL) {
            munmap(buffer, buffer_size);
        }
        close(fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    CLEAR(cap);
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: /dev/video0 is not a video capture device\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: /dev/video0 does not support streaming I/O\n");
        close(fd);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = params->width;
    fmt.fmt.pix.height = params->height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    params->buffer_size = buf.length;
    params->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (params->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    params->frame_nr = 0;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(params->buffer, params->buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(camera_params_t *params) {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

    FILE *fp = fopen("image_" + to_string(params->frame_nr) + ".yuv", "wb");
    if (fp == NULL) {
        perror("Error opening image file");
        return -1;
    }

    fwrite(params->buffer, 1, params->buffer_size, fp);
    fclose(fp);

    params->frame_nr++;
    return 0;
}

// Function to release the camera resources
void release_camera(camera_params_t *params) {
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    if (buffer != NULL) {
        munmap(buffer, buffer_size);
    }
    close(fd);
}

int main() {
    camera_params_t params;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the camera
    if (init_camera(&params) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("camera_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        release_camera(&params);
        return 1;
    }

    // Capture an image
    if (capture_image(&params) < 0) {
        fprintf(stderr, "Image capture failed\n");
        fclose(log_file);
        release_camera(&params);
        return 1;
    }

    // Log the image capture event
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    fprintf(log_file, "%s: Captured image %d\n", buf, params.frame_nr);
    fflush(log_file);

    // Release the camera resources
    fclose(log_file);
    release_camera(&params);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for line %d\n", line->line_number);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_release_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";
    config.release = 1;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
