#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define MAX_BUFFER 256

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    int uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER];
    ssize_t bytes_read;

    printf("Starting data exchange. Press Ctrl+C to exit.\n");

    while (keep_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        } else {
            // No data available, sleep briefly to avoid busy-waiting
            usleep(10000); // 10ms
        }
    }

    close(uart_fd);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

