#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define DHT22_GPIO 4

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i;
    int bit_idx = 0;
    int byte_idx = 0;
    int data_bytes[5] = {0, 0, 0, 0, 0};
    int pulse_lengths[80] = {0};

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 based on DHT22 datasheet

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal\n");
        return data; // Return invalid data
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal high\n");
        return data; // Return invalid data
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for end signal\n");
        return data; // Return invalid data
    }

    // Read the 40 bits of data
    for (i = 0; i < 80; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // Wait 1ms
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit start\n");
            return data; // Return invalid data
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // Wait 1ms
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit end\n");
            return data; // Return invalid data
        }
        long end = gpioTick();

        pulse_lengths[i] = end - start;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if (pulse_lengths[i] > 40) {
            data_bytes[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    // Verify checksum
    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) != data_bytes[4]) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return data; // Return invalid data
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data.temperature *= -1.0;
    }

    data.valid = 1;
    return data;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    DHT22Data dht22_data;

    while (1) {
        dht22_data = read_dht22();

        if (dht22_data.valid) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", dht22_data.temperature, dht22_data.humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line23, *line24, *line25;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the state of a GPIO line
int set_gpio_state(int line, int value) {
    int ret;
    struct gpiod_line_request_config config;

    // Request the line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", line, strerror(-ret));
        return -1;
    }

    // Set the value of the line
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting value of line %d: %s\n", line, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to report the state applied to a GPIO line
void report_gpio_state(int line, int value) {
    printf("GPIO %d set to %d\n", line, value);
}

int main() {
    int ret;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the lines for the GPIOs
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    line25 = gpiod_chip_get_line(chip, GPIO_25);

    if (!line17 || !line23 || !line24 || !line25) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 17 to HIGH
        if (set_gpio_state(GPIO_17, 1) == 0) {
            report_gpio_state(GPIO_17, 1);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_17);
        }

        // Set GPIO 23 to LOW
        if (set_gpio_state(GPIO_23, 0) == 0) {
            report_gpio_state(GPIO_23, 0);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_23);
        }

        // Set GPIO 24 to HIGH
        if (set_gpio_state(GPIO_24, 1) == 0) {
            report_gpio_state(GPIO_24, 1);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_24);
        }

        // Set GPIO 25 to LOW
        if (set_gpio_state(GPIO_25, 0) == 0) {
            report_gpio_state(GPIO_25, 0);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_25);
        }

        sleep(10);
    }

    // Release the lines
    if (line17) gpiod_line_release(line17);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (line25) gpiod_line_release(line25);

    // Close the chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/adc"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0 // MCP3008 channel to read
#define NUM_SENSORS 3
#define SAMPLE_INTERVAL_MS 1000 // Sample every 1 second

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int spi_handle = -1;
static int spi_channel = SPI_CHANNEL;
static int spi_speed = SPI_SPEED;
static int adc_channel = ADC_CHANNEL;
static int num_sensors = NUM_SENSORS;
static int sample_interval_ms = SAMPLE_INTERVAL_MS;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    int reading;
} sensor_data_t;

// Function prototypes
int read_mcp3008(int channel);
void publish_mqtt(int sensor_id, int reading);
void signal_handler(int sig);
void cleanup();
void *sensor_thread(void *arg);
void log_message(int priority, const char *message);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message(LOG_ERR, "Invalid ADC channel");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    // Transfer data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        log_message(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to publish MQTT message
void publish_mqtt(int sensor_id, int reading) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"sensor_id\": %d, \"reading\": %d}", sensor_id, reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        log_message(LOG_INFO, "SPI closed");
    }

    if (mosq) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        log_message(LOG_INFO, "MQTT client destroyed");
    }

    gpioTerminate();
    log_message(LOG_INFO, "pigpio terminated");

    closelog();
    log_message(LOG_INFO, "System logging stopped");
}

// Thread function to read and publish sensor data
void *sensor_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning

    while (running) {
        for (int i = 0; i < num_sensors; i++) {
            int reading = read_mcp3008(adc_channel);
            if (reading >= 0) {
                publish_mqtt(i, reading);
                log_message(LOG_INFO, "Sensor %d: Reading = %d", i, reading);
            } else {
                log_message(LOG_ERR, "Failed to read sensor %d", i);
            }
        }
        gpioDelay(sample_interval_ms * 1000); // Delay in microseconds
    }

    return NULL;
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    openlog("sensor_publisher", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "b:p:c:d:i:")) != -1) {
        switch (opt) {
            case 'b':
                MQTT_BROKER = optarg;
                break;
            case 'p':
                MQTT_PORT = atoi(optarg);
                break;
            case 'c':
                spi_channel = atoi(optarg);
                break;
            case 'd':
                spi_speed = atoi(optarg);
                break;
            case 'i':
                sample_interval_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-b broker_address] [-p broker_port] [-c spi_channel] [-d spi_speed] [-i sample_interval_ms]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "MQTT client initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connection failed: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sensor reading thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor thread\n");
        cleanup();
        return 1;
    }

    // Wait for the thread to finish (which will only happen on signal)
    pthread_join(thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static void *buffer = NULL;
static unsigned int buffer_size = 0;
static int width = 640;
static int height = 480;
static int frame_nr = 0;
static char *device_name = "video0";
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "Ctrl+C pressed. Exiting.\n");
        keep_running = 0;
    }
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main(int argc, char **argv) {
    int opt;
    char filename[256];

    signal(SIGINT, signal_handler);

    while ((opt = getopt(argc, argv, "d:w:h:b:")) != -1) {
        switch (opt) {
            case 'd':
                device_name = optarg;
                break;
            case 'w':
                width = atoi(optarg);
                break;
            case 'h':
                height = atoi(optarg);
                break;
            case 'b':
                buffer_size = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device] [-w width] [-h height] [-b buffer_size]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (width <= 0 || height <= 0 || buffer_size <= 0) {
        fprintf(stderr, "Width and height must be positive integers, and buffer size must be positive.\n");
        exit(EXIT_FAILURE);
    }

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct v4l2_capability cap;
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Use MJPEG for simplicity
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device_name, strerror(errno));
        exit(EXIT_FAILURE);
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == 0) {
            fwrite(buffer, 1, buf.bytesused, fp);
            frame_nr++;
            printf("Captured frame %d\n", frame_nr);
        } else {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    if (munmap(buffer, buffer_size) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
    }

    close(fd);
    printf("Image saved to %s\n", filename);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM range
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_6, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_6, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 500); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 500);
        gpioPWM(PWM_PIN_3, 500);
        gpioPWM(PWM_PIN_4, 500);
        gpioPWM(PWM_PIN_5, 500);
        gpioPWM(PWM_PIN_6, 500);

        // Print current duty cycles
        printf("PWM Duty Cycles: %d %d %d %d %d %d\n", gpioGetPWMdutycycle(PWM_PIN_1), gpioGetPWMdutycycle(PWM_PIN_2), gpioGetPWMdutycycle(PWM_PIN_3), gpioGetPWMdutycycle(PWM_PIN_4), gpioGetPWMdutycycle(PWM_PIN_5), gpioGetPWMdutycycle(PWM_PIN_6));

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Stop PWM output for all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);
    gpioPWM(PWM_PIN_6, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
        printf("Caught SIGINT, exiting...\n");
    }
}

int main() {
    int ret;

    // Register signal handler
