#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define PCF8574_ADDR 0x27

// Define the GPIO pins connected to the PCF8574
#define PCF8574_RS 22
#define PCF8574_E 23
#define PCF8574_D4 24
#define PCF8574_D5 25
#define PCF8574_D6 4
#define PCF8574_D7 17

// Define the range of values to display
#define MIN_VALUE 0
#define MAX_VALUE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the I2C bus
int i2c_init(int i2c_bus, int i2c_address)
{
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to set the GPIO pins for output
void set_gpio_output(int rs_pin, int e_pin, int d4_pin, int d5_pin, int d6_pin, int d7_pin)
{
    gpioSetMode(rs_pin, PI_OUTPUT);
    gpioSetMode(e_pin, PI_OUTPUT);
    gpioSetMode(d4_pin, PI_OUTPUT);
    gpioSetMode(d5_pin, PI_OUTPUT);
    gpioSetMode(d6_pin, PI_OUTPUT);
    gpioSetMode(d7_pin, PI_OUTPUT);
}

// Function to write a byte to the PCF8574
void write_byte(int i2c_handle, int data)
{
    // Set RS low to select the data byte
    gpioWrite(PCF8574_RS, 0);

    // Set E high to enable the write
    gpioWrite(PCF8574_E, 1);

    // Send the data byte to the PCF8574
    char buf[8];
    buf[0] = data;
    for (int i = 1; i < 8; i++)
    {
        buf[i] = (data >> (7 - i)) & 0x01;
    }

    // Send the data byte to the PCF8574
    for (int i = 0; i < 8; i++)
    {
        gpioWrite(PCF8574_D4, buf[i]);
        gpioWrite(PCF8574_D5, (buf[i] >> 1) & 0x01);
        gpioWrite(PCF8574_D6, (buf[i] >> 2) & 0x01);
        gpioWrite(PCF8574_D7, (buf[i] >> 3) & 0x01);
    }

    // Disable E to disable the write
    gpioWrite(PCF8574_E, 0);

    // Set RS high to select the next byte
    gpioWrite(PCF8574_RS, 1);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C bus
    int i2c_handle = i2c_init(I2C_BUS, PCF8574_ADDR);
    if (i2c_handle < 0)
    {
        gpioTerminate();
        return 1;
    }

    // Set the GPIO pins for output
    set_gpio_output(PCF8574_RS, PCF8574_E, PCF8574_D4, PCF8574_D5, PCF8574_D6, PCF8574_D7);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop to display values
    while (!terminate)
    {
        for (int value = MIN_VALUE; value <= MAX_VALUE; value++)
        {
            write_byte(i2c_handle, value);
            gpioDelay(500000); // 0.5 seconds
        }
    }

    // Close the I2C bus
    i2cClose(i2c_handle);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

