// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int gpio_initialized = 0;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go HIGH (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go HIGH\n");
        return -1; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go LOW (end of pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go LOW\n");
        return -1; // Indicate error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            // Calculate distance in centimeters (speed of sound: 343 m/s)
            float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up and exit
    if (gpio_initialized) {
        gpioTerminate();
    }

    return 0;
}

