#include <sys/time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static void *buffer = NULL;
static unsigned int buffer_size = 0;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main(int argc, char **argv) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct timeval start, end;
    double elapsed;
    char filename[64];
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check if the camera device exists
    if (access("/dev/video0", F_OK) == -1) {
        fprintf(stderr, "Error: No video device found. Make sure the camera is connected and the v4l2 drivers are loaded.\n");
        return 1;
    }

    // Open the video device
    fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening video device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture.\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming.\n");
        close(fd);
        return 1;
    }

    // Set image format
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting image format");
        close(fd);
        return 1;
    }

    // Request buffers
    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    // Map the buffer
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(fd);
        return 1;
    }

    // Capture and save image
    gettimeofday(&start, NULL);
    while (keep_running) {
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                usleep(10000); // Sleep for 10ms
                continue;
            } else {
                perror("Error dequeuing buffer");
                break;
            }
        }

        // Get timestamp
        gettimeofday(&end, NULL);
        elapsed = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;

        // Create filename with timestamp
        snprintf(filename, sizeof(filename), "image_%ld.jpg", (long)elapsed);

        // Save image to file
        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            perror("Error opening file for writing");
            break;
        }
        fwrite(buffer, 1, buf.bytesused, fp);
        fclose(fp);

        // Requeue the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error requeuing buffer");
            break;
        }

        gettimeofday(&start, NULL);
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
    }

    // Unmap the buffer
    if (munmap(buffer, buffer_size) == -1) {
        perror("Error unmapping buffer");
    }

    // Close the device
    if (close(fd) == -1) {
        perror("Error closing device");
    }

    printf("Image capture complete. Exiting.\n");
    return 0;
}

