    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Set PWM duty cycle (0-255)
    gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
    gpioPWM(PWM_PIN_2, 192); // 75% duty cycle
    gpioPWM(PWM_PIN_3, 64);  // 25% duty cycle

    printf("PWM output started. Press Ctrl+C to exit.\n");

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    while (program_running) {
        // Do nothing, just wait for the signal
        gpioDelay(100000); // 0.1 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line;
static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    int ret;
    struct timespec start, end;
    long long duration;
    double distance;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines
    ret = gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    if (ret < 0) {
        perror("Error requesting trigger line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTION_INPUT, 0);
    if (ret < 0) {
        perror("Error requesting echo line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Trigger the sensor
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret < 0) {
            perror("Error setting trigger line value");
            break;
        }
        usleep(10); // 10us trigger pulse

        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret < 0) {
            perror("Error setting trigger line value");
            break;
        }

        // Measure echo pulse
        int timeout = 1000; // Timeout after 1ms
        while (running) {
            ret = gpiod_line_get_value(echo_line);
            if (ret < 0) {
                perror("Error getting echo line value");
                break;
            }
            if (ret == 1) {
                break; // Echo started
            } else if (timeout-- == 0) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
            usleep(1); // Check every 1us
        }

        if (!running) break;

        timeout = 1000; // Reset timeout
        while (running) {
            ret = gpiod_line_get_value(echo_line);
            if (ret < 0) {
                perror("Error getting echo line value");
                break;
            }
            if (ret == 0) {
                break; // Echo ended
            } else if (timeout-- == 0) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
            usleep(1); // Check every 1us
        }

        if (!running) break;

        // Calculate duration
        clock_gettime(CLOCK_MONOTONIC, &start);
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

        // Calculate distance
        distance = (double)duration / 29.1 / 2.0;

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        usleep(50000); // 50ms delay
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

