#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize a GPIO line
int init_gpio(struct gpiod_chip *chip, int pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";

    int ret = gpiod_line_request(*line, &config, 0); // Request the line for output
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d\n", pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for line %d\n", line->line_number);
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO line
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for line %d\n", line->line_number);
        return -1;
    }
    return value;
}

// Function to check the validity of the reading
int validate_reading(int reading) {
    // Basic validation: check if the reading is 0 or 1
    if (reading != 0 && reading != 1) {
        fprintf(stderr, "Error: Invalid reading: %d\n", reading);
        return -1;
    }
    return 0;
}

// Function to report the state applied to standard output
void report_state(int pin, int value) {
    printf("Applied state to GPIO %d: %d\n", pin, value);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Initialize GPIO lines
    if (init_gpio(chip, GPIO_PIN_1, &line1) < 0 ||
        init_gpio(chip, GPIO_PIN_2, &line2) < 0 ||
        init_gpio(chip, GPIO_PIN_3, &line3) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3 && !terminate; ++i) {
        // Simulate sensor readings
        int reading1 = read_gpio_state(line1);
        int reading2 = read_gpio_state(line2);
        int reading3 = read_gpio_state(line3);

        if (reading1 < 0 || reading2 < 0 || reading3 < 0) {
            fprintf(stderr, "Error: Failed to read sensor data. Skipping cycle.\n");
            sleep(5);
            continue;
        }

        // Validate readings
        if (validate_reading(reading1) < 0 || validate_reading(reading2) < 0 || validate_reading(reading3) < 0) {
            fprintf(stderr, "Error: Invalid sensor reading. Skipping cycle.\n");
            sleep(5);
            continue;
        }

        // Apply state to GPIOs
        if (set_gpio_state(line1, reading1) < 0 || set_gpio_state(line2, reading2) < 0 || set_gpio_state(line3, reading3) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO state. Skipping cycle.\n");
            sleep(5);
            continue;
        }

        // Report state
        report_state(GPIO_PIN_1, reading1);
        report_state(GPIO_PIN_2, reading2);
        report_state(GPIO_PIN_3, reading3);

        sleep(5);
    }

    // Release GPIO lines
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

