    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %d\n", line->line_number, ret);
        return -1;
    }
    return 0;
}

// Function to export a GPIO line
int export_gpio(struct gpiod_chip *chip, int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO %d line\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d line: %d\n", pin, ret);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO line
int unexport_gpio(struct gpiod_chip *chip, int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO %d line for unexport\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d line for unexport: %d\n", pin, ret);
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO %d line: %d\n", pin, ret);
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Export GPIO lines
    if (export_gpio(chip, GPIO_17) < 0 ||
        export_gpio(chip, GPIO_22) < 0 ||
        export_gpio(chip, GPIO_27) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line17 || !line22 || !line27) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial states
    if (set_gpio_state(line17, 1) < 0 ||
        set_gpio_state(line22, 0) < 0 ||
        set_gpio_state(line27, 1) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_17, 1, GPIO_22, 0, GPIO_27, 1);

    // Main loop
    while (keep_running) {
        sleep(1);
    }

    // Release GPIO lines and chip
    if (set_gpio_state(line17, 0) < 0 ||
        set_gpio_state(line22, 0) < 0 ||
        set_gpio_state(line27, 0) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_release(line17);
    gpiod_line_release(line22);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

