#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled

int i2c_fd = -1; // Global file descriptor for I2C
volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to write a command to the SHT31
int write_command(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the SHT31
int read_data(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    float temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    float humidity = 100.0 * (float)humidity_raw / 65535.0;

    return (sensor_data_t){temperature, humidity};
}

// Function to validate the sensor readings
int validate_data(const sensor_data_t *data) {
    if (data->temperature < -40.0 || data->temperature > 125.0) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0.0 || data->humidity > 100.0) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", data->humidity);
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        uint8_t data[6];
        uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};

        // Write measurement command
        if (write(i2c_fd, command, 2) != 2) {
            perror("Error writing measurement command");
            close(i2c_fd);
            return 1;
        }

        // Wait for measurement (typical 10ms for high repeatability)
        usleep(20000); // 20ms

        // Read data
        if (read(i2c_fd, data, 6) != 6) {
            perror("Error reading data");
            close(i2c_fd);
            return 1;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Validate data
        if (validate_data(&sensor_data) != 0) {
            fprintf(stderr, "Error: Invalid sensor data\n");
        } else {
            // Print data
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
