#include <unistd.h>

// Define GPIO pins
const int gpio_pins[] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[10]; // Assuming a maximum of 10 lines

// Function prototypes
int initialize_gpio();
void set_gpio_output(int pin, int value);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            gpiod_chip_close(chip);
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "output";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) != 0) {
            perror("Error requesting GPIO line");
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Sets the output value of a GPIO line
void set_gpio_output(int pin, int value) {
    for (int i = 0; i < num_pins; i++) {
        if (gpio_pins[i] == pin) {
            if (gpiod_line_set_value(lines[i], value) != 0) {
                perror("Error setting GPIO value");
            }
            return; // Exit after finding the pin
        }
    }
    fprintf(stderr, "Error: GPIO pin %d not found\n", pin);
}

// Cleans up GPIO resources
void cleanup_gpio() {
    for (int i = 0; i < num_pins; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Example usage: Set GPIO 5 to HIGH
    set_gpio_output(5, 1); // Set GPIO 5 to HIGH
    printf("GPIO %d set to HIGH\n", 5);

    // Keep the program running
    while (1) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

