#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (0-100)
#define PWM_DUTY_CYCLE 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM duty cycle for all pins
    gpioPWM(PWM_PIN_1, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_4, PWM_DUTY_CYCLE);

    // Print the state applied to each pin
    printf("PWM state applied:\n");
    printf("GPIO %d: %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
    printf("GPIO %d: %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));
    printf("GPIO %d: %d\n", PWM_PIN_3, gpioGetPWMdutycycle(PWM_PIN_3));
    printf("GPIO %d: %d\n", PWM_PIN_4, gpioGetPWMdutycycle(PWM_PIN_4));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to keep the program running until Ctrl+C is pressed
    while (program_running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Stop PWM on all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0); // Request the line for output
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for output: %s\n", pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value of line %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int pin) {
    struct gpiod_line_release_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d for unexport\n", pin);
        return -1;
    }

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release line %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(GPIO_PIN_1) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (export_gpio(GPIO_PIN_2) < 0) {
        unexport_gpio(GPIO_PIN_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 2 to HIGH
        if (set_gpio_state(line1, 1) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_1);

        // Set GPIO 3 to LOW
        if (set_gpio_state(line2, 0) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_2);

        sleep(1);
    }

    // Unexport GPIO pins
    if (unexport_gpio(GPIO_PIN_1) < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO %d\n", GPIO_PIN_1);
    }
    if (unexport_gpio(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO %d\n", GPIO_PIN_2);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

