}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM output
    gpioSetMode(PWM_GPIO_1, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_2, PI_OUTPUT);
    gpioSetMode(PWM_GPIO_3, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_GPIO_1, 255);
    gpioSetPWMrange(PWM_GPIO_2, 255);
    gpioSetPWMrange(PWM_GPIO_3, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_GPIO_1, 1000);
    gpioSetPWMfrequency(PWM_GPIO_2, 1000);
    gpioSetPWMfrequency(PWM_GPIO_3, 1000);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Apply PWM duty cycle (0-255) to each GPIO
        gpioPWM(PWM_GPIO_1, 128); // 50% duty cycle
        gpioPWM(PWM_GPIO_2, 192); // 75% duty cycle
