#include <time.h>

#define DHT22_GPIO 4

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i;
    int bit = 0;
    int byte = 0;
    int data_array[5] = {0, 0, 0, 0, 0};
    int j;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout issues

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read 40 bits (5 bytes)
    for (i = 0; i < 40; i++) {
        // Wait for the start of the bit (low)
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            count++;
            if (count > 100) {
                data.valid = 0;
                return data;
            }
            gpioDelay(1);
        }

        // Measure the length of the high pulse
        count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            if (count > 100) {
                data.valid = 0;
                return data;
            }
            gpioDelay(1);
        }

        // Determine if it's a 0 or a 1 based on the pulse length
        if (count > 40) {
            data_array[byte] |= (1 << (7 - bit));
        }

        bit++;
        if (bit == 8) {
            bit = 0;
            byte++;
        }
    }

    // Checksum validation
    if ((data_array[0] + data_array[1] + data_array[2] + data_array[3]) != data_array[4]) {
        data.valid = 0;
        return data;
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((data_array[0] << 8) | data_array[1]) / 10.0;
    data.temperature = (float)(((data_array[2] & 0x7F) << 8) | data_array[3]) / 10.0;
    if (data_array[2] & 0x80) {
        data.temperature *= -1.0;
    }

    data.valid = 1;
    return data;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int cycle_count = 0;
    while (cycle_count < 3) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            printf("Cycle %d: Temperature: %.1f C, Humidity: %.1f %%\n", cycle_count + 1, dht22_data.temperature, dht22_data.humidity);
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed\n", cycle_count + 1);
        }

        cycle_count++;
        sleep(5);
    }

    gpioTerminate();
    return 0;
}

