        report_gpio_state(GPIO_9, 0);
        set_gpio_pins(GPIO_10, 1);
        report_gpio_state(GPIO_10, 1);
        set_gpio_pins(GPIO_11, 0);
        report_gpio_state(GPIO_11, 0);
        set_gpio_pins(GPIO_23, 1);
