        return -1;
    }
    return 0;
}

// Function to export the GPIO line
int export_gpio()
{
    int ret;

    ret = gpiod_line_request(line, "gpio_export", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to unexport the GPIO line
int unexport_gpio()
{
