#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 16
#define GPIO_PIN_2 20

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0); // Request the line for output
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for output: %s\n", pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value of line %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_release_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d for unexport\n", pin);
        return -1;
    }

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release line %d: %s\n", line->line_number, strerror(-ret));
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(GPIO_PIN_1) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (export_gpio(GPIO_PIN_2) < 0) {
        unexport_gpio(GPIO_PIN_1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO 16 to HIGH
        if (set_gpio_state(line1, 1) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_1);

        // Set GPIO 20 to LOW
        if (set_gpio_state(line2, 0) < 0) {
            unexport_gpio(GPIO_PIN_1);
            unexport_gpio(GPIO_PIN_2);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_2);

        usleep(100000); // 0.1 seconds
    }

    // Unexport GPIO pins
    if (unexport_gpio(GPIO_PIN_1) < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO %d\n", GPIO_PIN_1);
    }
    if (unexport_gpio(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO %d\n", GPIO_PIN_2);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

int spi_fd;

// Function to initialize the SPI device
int spi_init()
{
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from the MAX31855
int read_max31855(uint32_t *raw_data)
{
    uint8_t tx_buf[4] = {0}; // Dummy data for reading
    uint8_t rx_buf[4] = {0};
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    *raw_data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];

    return 0;
}

// Function to process the raw data and extract temperature
float process_data(uint32_t raw_data)
{
    // Check for fault bits
    if (raw_data & 0x00000007) {
        fprintf(stderr, "Fault detected: 0x%08X\n", raw_data);
        return -1000.0; // Indicate an error
    }

    // Extract temperature (bits 31:18)
    int32_t temp_raw = (raw_data >> 18) & 0x3FFF; // Mask out the relevant bits
    if (temp_raw & 0x2000) {
        temp_raw |= 0xFFFFC000; // Sign extend if negative
    }

    return temp_raw * 0.25;
}

int main()
{
    if (spi_init() < 0) {
        return 1;
    }

    uint32_t raw_data;
    float temperature;

    while (1) {
        if (read_max31855(&raw_data) == 0) {
            temperature = process_data(raw_data);
            if (temperature > -999.0) {
                printf("Temperature: %.2f °C\n", temperature);
            } else {
                fprintf(stderr, "Error processing temperature data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read MAX31855 data.\n");
        }

        sleep(1);
    }

    close(spi_fd);
    return 0;
}

