#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18
#define PIR_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int pir_state = 0;
static volatile int program_running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void pir_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to trigger the HC-SR04 sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset flag for new measurement
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set flag to indicate echo received
    }
}

// Callback function for PIR sensor
void pir_callback(int gpio, int level, uint32_t tick) {
    pir_state = level;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Set pull-down resistor for PIR pin
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    // Register callback functions
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);
    gpioSetAlertFuncEx(PIR_PIN, pir_callback, NULL);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("HC-SR04 and PIR sensor interface started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_pulse();
        gpioDelay(50); // Delay between measurements

        // Calculate pulse width and distance
        int pulse_width = echo_end_tick - echo_start_tick;
        float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

        // Check for timeout
        if (pulse_width > TIMEOUT_US) {
            printf("Timeout: No echo received.\n");
            continue; // Skip to the next measurement
        }

        // Check PIR sensor state
        pir_state = gpioRead(PIR_PIN);

        // Control LED based on PIR sensor state
        if (pir_state == 1) {
            gpioWrite(LED_PIN, 1); // Turn on LED
        } else {
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        // Print sensor readings
        printf("Distance: %.2f cm, PIR: %d\n", distance, pir_state);

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 18
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile int keep_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export the GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_chip_get_line(chip, pin, &line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Important: Set to input

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Export the GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to toggle the GPIO pin state
    for (int i = 0; i < 10 && keep_running; ++i) {
        if (set_gpio_state(line, 1) == 0) {
            printf("GPIO %d set HIGH\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", GPIO_PIN);
        }
        usleep(500000); // 500ms

        if (set_gpio_state(line, 0) == 0) {
            printf("GPIO %d set LOW\n", GPIO_PIN);
        } else {
            fprintf(stderr, "Failed to set GPIO %d LOW\n", GPIO_PIN);
        }
        usleep(500000); // 500ms
    }

    // Unexport the GPIO pin
    if (unexport_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

#define I2C_DEVICE "/dev/i2c-1"

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

// Function to read calibration data from BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t buffer[26];
    if (read(fd, buffer, 26) != 26) {
        perror("Failed to read calibration data");
        return -1;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from BMP280
int read_raw_data(int fd, int32_t *raw_temperature, int32_t *raw_pressure) {
    uint8_t buffer[6];

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read raw data");
        return -1;
    }

    *raw_pressure = (int32_t)buffer[0] << 12 | (int32_t)buffer[1] << 4 | (int32_t)buffer[2] >> 4;
    *raw_temperature = (int32_t)buffer[3] << 12 | (int32_t)buffer[4] << 4 | (int32_t)buffer[5] >> 4;

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data *calib, int32_t *t_fine) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib->dig_T1) / 1024.0) * ((double)calib->dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib->dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib->dig_T1) / 8192.0)) * ((double)calib->dig_T3);
    *t_fine = (int32_t)(var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, struct bmp280_calib_data *calib, int32_t t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib->dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib->dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib->dig_P4) * 65536.0);
    var1 = (((double)calib->dig_P3) * var1 * var1 / 524288.0 + ((double)calib->dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib->dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib->dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib->dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib->dig_P7)) / 16.0;
    return p;
}

int main() {
    int fd;
    struct bmp280_calib_data calib;
    int32_t raw_temperature, raw_pressure;
    int32_t t_fine;
    double temperature, pressure;

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) < 0) {
        close(fd);
        return 1;
    }

    // Set the BMP280 to forced mode
    uint8_t config = (0x00 << 5) | (0x00 << 2) | 0x00; // t_sb = 0.5ms, filter = off, spi3w_en = off
    uint8_t ctrl_meas = (0x03 << 5) | (0x03 << 2) | 0x03; // osrs_t = x1, osrs_p = x1, mode = forced

    uint8_t buf[2];
    buf[0] = BMP280_REG_CONFIG;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write config register");
        close(fd);
        return 1;
    }
    buf[0] = config;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write config register");
        close(fd);
        return 1;
    }

    buf[0] = BMP280_REG_CTRL_MEAS;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write ctrl_meas register");
        close(fd);
        return 1;
    }
    buf[0] = ctrl_meas;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write ctrl_meas register");
        close(fd);
        return 1;
    }

    // Read 3 measurements
    for (int i = 0; i < 3; i++) {
        // Wait for measurement to complete (adjust delay as needed)
        usleep(10000); // 10ms

        if (read_raw_data(fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            close(fd);
            return 1;
        }

        temperature = compensate_temperature(raw_temperature, &calib, &t_fine);
        pressure = compensate_pressure(raw_pressure, &calib, t_fine);

        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_lines[4];
struct gpiod_chip *chip;

// Function prototypes
int initialize_gpio();
void set_gpio_output(int gpio);
void set_gpio_input(int gpio);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_lines[0] = gpiod_chip_get_line(chip, GPIO_17);
    gpio_lines[1] = gpiod_chip_get_line(chip, GPIO_22);
    gpio_lines[2] = gpiod_chip_get_line(chip, GPIO_23);
    gpio_lines[3] = gpiod_chip_get_line(chip, GPIO_24);

    if (!gpio_lines[0] || !gpio_lines[1] || !gpio_lines[2] || !gpio_lines[3]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set direction to output for all lines
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(gpio_lines[i], "gpio_control", 0) < 0) {
            perror("Error requesting GPIO line as output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to set GPIO output
void set_gpio_output(int gpio) {
    int index = -1;
    switch (gpio) {
        case GPIO_17: index = 0; break;
        case GPIO_22: index = 1; break;
        case GPIO_23: index = 2; break;
        case GPIO_24: index = 3; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio); return;
    }

    if (gpiod_line_set_value(gpio_lines[index], 1) < 0) {
        perror("Error setting GPIO value");
    }
    printf("GPIO %d set to output\n", gpio);
}

// Function to set GPIO input
void set_gpio_input(int gpio) {
    int index = -1;
    switch (gpio) {
        case GPIO_17: index = 0; break;
        case GPIO_22: index = 1; break;
        case GPIO_23: index = 2; break;
        case GPIO_24: index = 3; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio); return;
    }

    if (gpiod_line_set_value(gpio_lines[index], 0) < 0) {
        perror("Error setting GPIO value");
    }
    printf("GPIO %d set to input\n", gpio);
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    for (int i = 0; i < 4; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        set_gpio_output(GPIO_17);
        set_gpio_input(GPIO_22);
        set_gpio_output(GPIO_23);
        set_gpio_input(GPIO_24);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 18
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 0

static volatile int keep_running = 1;

void signal_handler(int sig)
{
    if (sig == SIGINT)
    {
        printf("Ctrl+C pressed. Exiting.\n");
        keep_running = 0;
    }
}

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line)
    {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio18", 0);
    if (ret < 0)
    {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running)
    {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0)
        {
            perror("Error reading GPIO value");
            break; // Exit loop on error
        }

        // Validate GPIO reading
        if (value != 0 && value != 1)
        {
            fprintf(stderr, "Invalid GPIO reading: %d\n", value);
            break; // Exit loop on invalid reading
        }

        // Apply GPIO state
        ret = gpiod_line_set_value(line, value);
        if (ret < 0)
        {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Print GPIO state
        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_LINE 0
#define GPIO_PATH "/sys/class/gpio/gpio17"

int main() {
    int ret;
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    int value;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    request = gpiod_line_request(line, &config, 0);
    if (!request) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set GPIO value to 1
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_line_request_release(request);
        return 1;
    }

    printf("GPIO %d set to 1\n", GPIO_PIN);

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_line_request_release(request);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables for calibration data
static uint16_t dig_T1;
static int16_t dig_T2;
static int16_t dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2;
static int16_t dig_P3;
static int16_t dig_P4;
static int16_t dig_P5;
static int16_t dig_P6;
static int16_t dig_P7;
static int16_t dig_P8;
static int16_t dig_P9;
static uint8_t dig_H1;
static int16_t dig_H2;
static uint8_t dig_H3;
static int16_t dig_H4;
static int16_t dig_H5;
static int8_t dig_H6;

// Global variable for I2C file descriptor
static int i2c_fd = -1;

// Signal handler for Ctrl+C
static volatile sig_atomic_t keep_running = 1;

static void int_handler(int dummy)
{
    keep_running = 0;
}

// Function to read a single byte from an I2C register
static int read_register(int fd, uint8_t reg)
{
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to an I2C register
static int write_register(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
static int read_calibration_data(int fd)
{
    dig_T1 = (read_register(fd, BME280_REG_CALIB_00 + 1) << 8) | read_register(fd, BME280_REG_CALIB_00);
    dig_T2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 3) << 8) | read_register(fd, BME280_REG_CALIB_00 + 2));
    dig_T3 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 5) << 8) | read_register(fd, BME280_REG_CALIB_00 + 4));
    dig_P1 = (read_register(fd, BME280_REG_CALIB_00 + 7) << 8) | read_register(fd, BME280_REG_CALIB_00 + 6);
    dig_P2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 9) << 8) | read_register(fd, BME280_REG_CALIB_00 + 8));
    dig_P3 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 11) << 8) | read_register(fd, BME280_REG_CALIB_00 + 10));
    dig_P4 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 13) << 8) | read_register(fd, BME280_REG_CALIB_00 + 12));
    dig_P5 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 15) << 8) | read_register(fd, BME280_REG_CALIB_00 + 14));
    dig_P6 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 17) << 8) | read_register(fd, BME280_REG_CALIB_00 + 16));
    dig_P7 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 19) << 8) | read_register(fd, BME280_REG_CALIB_00 + 18));
    dig_P8 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 21) << 8) | read_register(fd, BME280_REG_CALIB_00 + 20));
    dig_P9 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 23) << 8) | read_register(fd, BME280_REG_CALIB_00 + 22));
    dig_H1 = read_register(fd, BME280_REG_CALIB_00 + 25);
    dig_H2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 27) << 8) | read_register(fd, BME280_REG_CALIB_00 + 26));
    dig_H3 = read_register(fd, BME280_REG_CALIB_00 + 28);
    dig_H4 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 29) << 4) | (read_register(fd, BME280_REG_CALIB_00 + 30) & 0x0F));
    dig_H5 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 31) << 4) | (read_register(fd, BME280_REG_CALIB_00 + 30) >> 4));
    dig_H6 = (int8_t)read_register(fd, BME280_REG_CALIB_00 + 32);

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
static int read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity)
{
    uint8_t msb, lsb, xlsb;

    msb = read_register(fd, BME280_REG_TEMP_MSB);
    lsb = read_register(fd, BME280_REG_TEMP_LSB);
    xlsb = read_register(fd, BME280_REG_TEMP_XLSB);
    *temperature = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | ((int32_t)xlsb >> 4);

    msb = read_register(fd, BME280_REG_PRESS_MSB);
    lsb = read_register(fd, BME280_REG_PRESS_LSB);
    xlsb = read_register(fd, BME280_REG_PRESS_XLSB);
    *pressure = ((int32_t)msb << 12) | ((int32_t)lsb << 4) | ((int32_t)xlsb >> 4);

    msb = read_register(fd, BME280_REG_HUM_MSB);
    lsb = read_register(fd, BME280_REG_HUM_LSB);
    *humidity = ((int32_t)msb << 8) | (int32_t)lsb;

    return 0;
}

// Function to compensate temperature
static float compensate_temperature(int32_t raw_temperature)
{
    double var1, var2, T;
    double adc_T = (double)raw_temperature;
    double dig_T1_double = (double)dig_T1;
    double dig_T2_double = (double)dig_T2;
    double dig_T3_double = (double)dig_T3;

    var1 = (adc_T / 16384.0 - dig_T1_double / 1024.0) * dig_T2_double;
    var2 = ((adc_T / 131072.0 - dig_T1_double / 8192.0) * (adc_T / 131072.0 - dig_T1_double / 8192.0)) * dig_T3_double;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure
static float compensate_pressure(int32_t raw_pressure, float t_fine)
{
    double var1, var2, p;
    double adc_P = (double)raw_pressure;
    double dig_P1_double = (double)dig_P1;
    double dig_P2_double = (double)dig_P2;
    double dig_P3_double = (double)dig_P3;
    double dig_P4_double = (double)dig_P4;
    double dig_P5_double = (double)dig_P5;
    double dig_P6_double = (double)dig_P6;
    double dig_P7_double = (double)dig_P7;
    double dig_P8_double = (double)dig_P8;
    double dig_P9_double = (double)dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6_double / 32768.0;
    var2 = var2 + var1 * dig_P5_double * 2.0;
    var2 = (var2 / 4.0) + (dig_P4_double * 65536.0);
    var1 = (dig_P3_double * var1 * var1 / 524288.0 + dig_P2_double * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1_double;
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9_double * p * p / 2147483648.0;
    var2 = p * dig_P8_double / 32768.0;
    p = p + (var1 + var2 + dig_P7_double) / 16.0;
    return (float)(p/100.0); // in hPa
}

// Function to compensate humidity
static float compensate_humidity(int32_t raw_humidity, float t_fine)
{
    double var_H;
    double adc_H = (double)raw_humidity;
    double dig_H1_double = (double)dig_H1;
    double dig_H2_double = (double)dig_H2;
    double dig_H3_double = (double)dig_H3;
    double dig_H4_double = (double)dig_H4;
    double dig_H5_double = (double)dig_H5;
    double dig_H6_double = (double)dig_H6;

    double var_H1 = t_fine - 76800.0;
    double var_H2 = (adc_H - (dig_H4_double * 64.0 + dig_H5_double / 16384.0 * var_H1)) * (dig_H2_double / 67108864.0 * (1.0 + dig_H6_double / 67108864.0 * var_H1 * (1.0 + dig_H3_double / 67108864.0 * var_H1)));
    double H = var_H1 * (1.0 - var_H2 / 100.0);
    if (H > 100.0)
    {
        H = 100.0;
    } else if (H < 0.0)
    {
        H = 0.0;
    }
    return (float)H;
}

// Function to read data from the BME280 sensor
static int read_bme280_data(int fd, float *temperature, float *pressure, float *humidity)
{
    int32_t raw_temperature, raw_pressure, raw_humidity;
    float t_fine;

    if (read_raw_data(fd, &raw_temperature, &raw_pressure, &raw_humidity) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    t_fine = compensate_temperature(raw_temperature);
    *temperature = t_fine;
    *pressure = compensate_pressure(raw_pressure, t_fine);
    *humidity = compensate_humidity(raw_humidity, t_fine);

    return 0;
}

// Function to print the sensor data
static void print_data(float temperature, float pressure, float humidity)
{
    printf("Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);
}

int main()
{
    int ret;
    float temperature, pressure, humidity;

    // Register signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Check the device ID
    int chip_id = read_register(i2c_fd, BME280_REG_ID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    // Set humidity oversampling to 1x
    if (write_register(i2c_fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Failed to write humidity control register\n");
        close(i2c_fd);
        return 1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (write_register(i2c_fd, BME280_REG_CTRL_MEAS, 0x25) != 0) {
        fprintf(stderr, "Failed to write control register\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        if (read_bme280_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            print_data(temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read BME280 data\n");
        }
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export the GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_chip_get_line(chip, pin, &line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin state
int set_gpio_state(int pin, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT; // Required for unexport

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %s\n", pin, strerror(-ret));
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Export the GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set the GPIO pin HIGH
        if (set_gpio_state(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error setting GPIO pin HIGH\n");
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);

        // Set the GPIO pin LOW
        if (set_gpio_state(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error setting GPIO pin LOW\n");
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport the GPIO pin
    if (unexport_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Error unexporting GPIO pin %d\n", GPIO_PIN);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700 (example configuration: gain 1/8, integration time 100ms)
    unsigned short config_value = 0x0000; // Default configuration
    if (i2cWriteWordData(i2c_handle, VEML7700_CONFIG, config_value) < 0) {
        fprintf(stderr, "Failed to write configuration to VEML7700\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS data from VEML7700
        int als_data = i2cReadWordData(i2c_handle, VEML7700_ALS_DATA);
        if (als_data < 0) {
            fprintf(stderr, "Failed to read ALS data from VEML7700\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Print ALS data to standard output
        printf("ALS Data: %d\n", als_data);

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        keep_running = 0;
    }
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 0; // Wait for 0 deciseconds (non-blocking)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    int uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return 1;
    }

    printf("UART setup complete. Reading data...\n");

    while (keep_running) {
        char buffer[256];
        int bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break; // Exit loop on error
        } else {
            // Timeout or no data
            //printf("Timeout or no data received.\n");
        }

        usleep(100000); // 0.1 seconds
    }

    close(uart_fd);
    printf("UART port closed. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
static volatile int running = 1;
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start_tick, uint32_t end_tick);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start_tick = tick;
        } else if (level == 0) // Falling edge
        {
            echo_end_tick = tick;
        }
    }
}

// Function to trigger the ultrasonic pulse
void trigger_pulse()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start_tick, uint32_t end_tick)
{
    if (start_tick == 0 || end_tick == 0) return -1.0; // Invalid reading
    if (start_tick > end_tick) return -1.0; // Invalid reading

    uint32_t diff = end_tick - start_tick;
    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    running = 0;
    printf("\nExiting gracefully...\n");
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor started. Press Ctrl+C to exit.\n");

    while (running)
    {
        // Trigger the ultrasonic pulse
        trigger_pulse();

        // Wait for echo to return
        int timeout_count = 0;
        while (echo_start_tick == 0 && timeout_count < TIMEOUT_US)
        {
            gpioDelay(1); // Wait 1 us
            timeout_count++;
        }

        if (echo_start_tick == 0)
        {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue; // Skip to the next iteration
        }

        timeout_count = 0;
        while (echo_end_tick == 0 && timeout_count < TIMEOUT_US)
        {
            gpioDelay(1); // Wait 1 us
            timeout_count++;
        }

        if (echo_end_tick == 0)
        {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue; // Skip to the next iteration
        }

        // Calculate the distance
        double distance = calculate_distance((uint32_t)echo_start_tick, (uint32_t)echo_end_tick);

        if (distance > 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else
        {
            fprintf(stderr, "Invalid distance reading\n");
