#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADXL345
int init_adxl345(int fd) {
    // Set ADXL345 to measure mode
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Could not acquire bus access and/or talk to slave.");
        return -1;
    }

    // Set ADXL345 to measure mode
    if (write(fd, "\0x08", 1) < 0) {
        perror("Error: Could not write to ADXL345.");
        return -1;
    }

    return 0;
}

// Function to read data from ADXL345
int read_adxl345(int fd, int *x, int *y, int *z) {
    unsigned char buffer[6];

    // Set ADXL345 to measure mode
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Could not acquire bus access and/or talk to slave.");
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axes)
    if (read(fd, buffer, 6) != 6) {
        perror("Error: Could not read from ADXL345.");
        return -1;
    }

    // Combine bytes to form 10-bit values
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

int main() {
    int x, y, z;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device.");
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from ADXL345
        if (read_adxl345(i2c_fd, &x, &y, &z) == 0) {
            // Print data to standard output
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading ADXL345 data.\n");
        }

        // Delay for 100 milliseconds
        usleep(100000);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

