volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the pulse width of the echo signal
long getPulseWidth()
{
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go HIGH (start of pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go LOW (end of pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor measurement started. Press Ctrl+C to exit.\n");

    while (!terminate)
    {
        triggerSensor();
        long pulse_width = getPulseWidth();

        if (pulse_width > 0)
        {
            // Calculate distance in centimeters (speed of sound: 343 m/s)
            float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0; // pulse_width in microseconds

            // Validate distance
            if (distance >= 0 && distance <= 400)
            {
                printf("Distance: %.2f cm\n", distance);
            }
            else
            {
                printf("Invalid distance reading: %.2f cm\n", distance);
            }
        }
        else
        {
            printf("Timeout error: No echo received\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

