#define TCS34725_CONTROL_PON      0x01  // Power ON

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF  // 2.4ms - 1 cycle
#define TCS34725_INTEGRATIONTIME_24MS   0xF6  // 24ms - 1024 cycles
#define TCS34725_INTEGRATIONTIME_50MS   0xEB  // 50ms - 2048 cycles
#define TCS34725_INTEGRATIONTIME_101MS  0xD5  // 101ms - 4096 cycles
#define TCS34725_INTEGRATIONTIME_154MS  0xC0  // 154ms - 5120 cycles
#define TCS34725_INTEGRATIONTIME_238MS  0xA0  // 238ms - 8192 cycles
#define TCS34725_INTEGRATIONTIME_300MS  0x80  // 300ms - 10240 cycles
#define TCS34725_INTEGRATIONTIME_384MS  0x70  // 384ms - 12288 cycles
#define TCS34725_INTEGRATIONTIME_456MS  0x60  // 456ms - 16384 cycles
#define TCS34725_INTEGRATIONTIME_655MS  0x50  // 655ms - 24576 cycles
#define TCS34725_INTEGRATIONTIME_786MS  0x40  // 786ms - 32768 cycles
#define TCS34725_INTEGRATIONTIME_915MS  0x30  // 915ms - 36864 cycles
#define TCS34725_INTEGRATIONTIME_1024MS 0x20  // 1024ms - 40960 cycles

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init();
int tcs34725_read_raw(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
void signal_handler(int signal);

// Signal handler to catch Ctrl+C and exit gracefully
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Initialize the TCS34725 sensor
int tcs34725_init() {
    uint8_t id;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Check the device ID
    if (read(i2c_fd, &id, 1) != 1) {
        perror("Error reading device ID");
        close(i2c_fd);
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", id);
        close(i2c_fd);
        return -1;
    }

    // Enable power and ALS
    uint8_t enable_value = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;
    if (write(i2c_fd, &enable_value, 1) != 1) {
        perror("Error writing to enable register");
        close(i2c_fd);
        return -1;
    }

    // Set integration time
    uint8_t atime_value = TCS34725_INTEGRATIONTIME_300MS;
    if (write(i2c_fd, &atime_value, 1) != 1) {
        perror("Error writing to integration time register");
        close(i2c_fd);
        return -1;
    }

    // Set control register (power on, no wait)
    uint8_t control_value = TCS34725_CONTROL_PON;
    if (write(i2c_fd, &control_value, 1) != 1) {
        perror("Error writing to control register");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read raw color data from the sensor
int tcs34725_read_raw(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t data[8];

    // Read all color data registers in one go
    if (read(i2c_fd, data, 8) != 8) {
        perror("Error reading color data");
        return -1;
    }

    *c = (data[1] << 8) | data[0];
    *r = (data[3] << 8) | data[2];
    *g = (data[5] << 8) | data[4];
    *b = (data[7] << 8) | data[6];

    return 0;
}

int main() {
    uint16_t r, g, b, c;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed. Exiting.\n");
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read raw color data
        if (tcs34725_read_raw(&r, &g, &b, &c) == 0) {
            // Print the color data
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program finished.\n");
    return 0;
}

