        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        value = 1;
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

