int initialize_gpio() {
    int i;
    for (i = 0; i < 7; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, GPIO_4 + i);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_4 + i);
            return -1;
        }
    }
    return 0;
}

// Function to set a GPIO line as output
int set_gpio_output(int gpio) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_lines[gpio - GPIO_4], &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set a GPIO line as input
int set_gpio_input(int gpio) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "input";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_lines[gpio - GPIO_4], &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as input\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(int gpio, int value) {
    if (gpiod_line_set_value(gpio_lines[gpio - GPIO_4], value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value\n", gpio);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO line
int unexport_gpio(int gpio) {
    if (gpiod_line_release(gpio_lines[gpio - GPIO_4]) < 0) {
        fprintf(stderr, "Error: Could not release GPIO line %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    int i;
    for (i = 0; i < 7; i++) {
        if (gpio_lines[i]) {
            if (unexport_gpio(GPIO_4 + i) < 0) {
                fprintf(stderr, "Error: Could not unexport GPIO line %d\n", GPIO_4 + i);
