#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static volatile int keep_running = 1;

void signal_handler(int sig);
int setup_gpio(int pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
void cleanup_gpio(struct gpiod_line *line);

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int setup_gpio(int pin, struct gpiod_line **line) {
    int ret;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "gpio_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;

    signal(SIGINT, signal_handler);

    if (setup_gpio(GPIO_PIN_1, &line1) < 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", GPIO_PIN_1);
        return 1;
    }
    if (setup_gpio(GPIO_PIN_2, &line2) < 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", GPIO_PIN_2);
        cleanup_gpio(line1);
        return 1;
    }

    printf("GPIO %d and %d set as output. Press Ctrl+C to exit.\n", GPIO_PIN_1, GPIO_PIN_2);

    while (keep_running) {
        if (set_gpio_output(line1, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_PIN_1);
        }
        if (set_gpio_output(line2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_PIN_2);
        }
        sleep(1);
        if (set_gpio_output(line1, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_PIN_1);
        }
        if (set_gpio_output(line2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_PIN_2);
        }
        sleep(1);
    }

    cleanup_gpio(line1);
    cleanup_gpio(line2);

    return 0;
}

