#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0, check your setup
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    int uart_fd;
    struct termios tty;
    fd_set readfds;
    struct timeval timeout;
    char buffer[256];
    ssize_t bytes_read;
    time_t rawtime;
    struct tm *timeinfo;

    // Install signal handler for Ctrl+C
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open the serial port
    uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("open");
        return 1;
    }

    // Get the current termios settings
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("tcgetattr");
        close(uart_fd);
        return 1;
    }

    // Set the baud rate
    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    // Configure the port
    tty.c_cflag |= (CLOCAL | CREAD);    // Enable receiver and set local mode
    tty.c_cflag &= ~PARENB;             // No parity
    tty.c_cflag &= ~CSTOPB;             // 1 stop bit
    tty.c_cflag &= ~CSIZE;              // Clear size bits
    tty.c_cflag |= CS8;                // 8 data bits
    tty.c_lflag = 0;                   // No signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                   // No remapping, no delays
    tty.c_cc[VMIN] = 0;                 // Read non-blocking
    tty.c_cc[VTIME] = 0;                // No timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; //Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; //Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VTXOF] = 0;  //Disable V.23/32/64 Vitterman stop signal processing
    tty.c_cc[VMIN] = 0;  //Read non-blocking
    tty.c_cc[VTIME] = 0; //No timeout

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(uart_fd);
        return 1;
    }

    printf("UART port %s opened successfully.\n", UART_PORT);

    while (keep_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred
            continue;
        } else {
            // Data is available
            bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0'; // Null-terminate the string
                printf("Received: %s\n", buffer);
            } else if (bytes_read == -1) {
                perror("read");
                break;
            } else {
                // No data available (or error)
                continue;
            }
        }
    }

    close(uart_fd);
    return 0;
}

