#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long getPulseWidth()
{
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= 10000)
    {
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width)
{
    return (pulse_width / 2.0) / 29.1;
}

// Function to control the LED
void controlLED(int state)
{
    gpioWrite(LED_PIN, state);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    while (!terminate)
    {
        triggerSensor();
        long pulse_width = getPulseWidth();

        if (pulse_width > 0)
        {
            float distance = calculateDistance(pulse_width);
            printf("Distance: %.2f cm\n", distance);
            controlLED(1); // Turn on LED
            gpioDelay(500);  // Wait 500ms
            controlLED(0); // Turn off LED
        } else {
            fprintf(stderr, "Timeout waiting for echo.\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

