    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int pin)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_export";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request(line, &config, 0); // Request the line
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d\n", pin);
        gpiod_line_release(line);
        return -1;
    }
    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for line %d\n", line->line_number);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int pin)
{
    struct gpiod_line_release_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_unexport";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d for unexport\n", pin);
        return -1;
    }

    int ret = gpiod_line_release(line, &config);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release line %d\n", pin);
        return -1;
    }
    return 0;
}

